@tailwind base;
@tailwind components;
@tailwind utilities;

[x-cloak] {
    display: none !important;
}

/*
 * Beach background: two fixed layers (day + night) that crossfade when the theme changes.
 * Fixed elements instead of background-attachment: fixed, which breaks on iOS/macOS Safari.
 * The html background color matches each image so there is no white flash before it loads.
 */
html {
    background-color: #97b5b2;
    scrollbar-gutter: stable;
}

html.dark {
    background-color: #1c2a48;
}

.theme-bg {
    position: fixed;
    inset: 0;
    z-index: -10;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    pointer-events: none;
    transition: none;
}

.theme-bg::after {
    content: '';
    position: absolute;
    inset: 0;
}

.theme-bg-day {
    background-image: url('/images/bg-day.webp');
    opacity: 1;
}

.theme-bg-day::after {
    background-color: rgb(255 255 255 / 0.2);
}

.theme-bg-night {
    background-image: url('/images/bg-night.webp');
    opacity: 0;
}

.theme-bg-night::after {
    background-color: rgb(15 23 42 / 0.4);
}

/*
 * Guest pages (login, register, password reset) use a dedicated hero photo
 * instead of the shared day/night crossfade. Set on the <body> of the guest
 * layout only, so authenticated pages keep the campus background.
 */
.guest-bg {
    min-height: 100vh;
}

.guest-bg::before {
    content: '';
    position: fixed;
    inset: 0;
    z-index: -10;
    background-image: url('/images/login-page.webp');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    pointer-events: none;
}

html.theme-transition .theme-bg {
    transition: opacity 700ms ease-in-out;
}

html.dark .theme-bg-day {
    opacity: 0;
}

html.dark .theme-bg-night {
    opacity: 1;
}

/* Added by applyTheme() for a moment while switching, so colors change together with the background. */
html.theme-transition *:not(.theme-bg),
html.theme-transition *:not(.theme-bg)::before,
html.theme-transition *:not(.theme-bg)::after {
    transition-property: background-color, border-color, color, fill, stroke !important;
    transition-duration: 300ms !important;
    transition-timing-function: ease-in-out !important;
}

@media (prefers-reduced-motion: reduce) {
    .theme-bg,
    html.theme-transition *,
    html.theme-transition *::before,
    html.theme-transition *::after {
        transition: none !important;
    }
}

@layer components {
    /* Content cards, tables, wizard panel and modals. Opaque enough for long forms. */
    .glass-panel {
        @apply border border-white/30 bg-white/75 shadow-sm backdrop-blur-md dark:border-white/10 dark:bg-slate-900/65;
    }

    /* Top navigation and page heading bars. */
    .glass-bar {
        @apply border-b border-white/20 bg-white/70 backdrop-blur-md dark:bg-slate-900/60;
    }

    /* Login, register and other guest pages. */
    .glass-card {
        @apply rounded-2xl border border-white/30 bg-white/60 shadow-2xl backdrop-blur-lg dark:border-white/10 dark:bg-slate-900/50;
    }

    /* Inputs, selects and textareas sitting on glass. */
    .glass-input {
        @apply border-gray-300 bg-white/70 text-gray-900 placeholder-gray-500 dark:border-white/10 dark:bg-slate-800/60 dark:text-gray-100 dark:placeholder-gray-400;
    }

    /* Without backdrop-filter the blur is lost, so use near-solid colors to keep text readable. */
    @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
        .glass-panel,
        .glass-bar,
        .glass-card {
            @apply bg-white/95 dark:bg-slate-900/95;
        }

        .glass-input {
            @apply bg-white dark:bg-slate-800;
        }
    }
}
